import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_31_algorithm_map.png",o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_31_experiment_matrix.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_31_evaluation_protocol.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_31_reproducibility.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_31_autonomous_driving_route.png",f=JSON.parse('{"title":"强化学习学完之后怎么做研究？从算法选择到可信评价","description":"强化学习学到算法推导、训练循环和常见方法之后，真正困难的问题才出现：面对一个新任务，为什么选这个算法？它究竟解决了哪个瓶颈？一次漂亮的训练曲线能不能说明方法有效？一篇可信的研究，核心不是把最新方法接到环境里，而是把问题、假设、对照、数据划分、统计分析和复现材料连成一条可检查的证据链。","frontmatter":{"title":"强化学习学完之后怎么做研究？从算法选择到可信评价","description":"强化学习学到算法推导、训练循环和常见方法之后，真正困难的问题才出现：面对一个新任务，为什么选这个算法？它究竟解决了哪个瓶颈？一次漂亮的训练曲线能不能说明方法有效？一篇可信的研究，核心不是把最新方法接到环境里，而是把问题、假设、对照、数据划分、统计分析和复现材料连成一条可检查的证据链。","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":19,"source":"2026-08-13/rl_series_31_research_evaluation.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_31_algorithm_map.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-31-research-evaluation"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"强化学习学完之后怎么做研究？从算法选择到可信评价"}],["meta",{"property":"og:description","content":"强化学习学到算法推导、训练循环和常见方法之后，真正困难的问题才出现：面对一个新任务，为什么选这个算法？它究竟解决了哪个瓶颈？一次漂亮的训练曲线能不能说明方法有效？一篇可信的研究，核心不是把最新方法接到环境里，而是把问题、假设、对照、数据划分、统计分析和复现材料连成一条可检查的证据链。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-31-research-evaluation"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_31_algorithm_map.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"强化学习学完之后怎么做研究？从算法选择到可信评价"}],["meta",{"name":"twitter:description","content":"强化学习学到算法推导、训练循环和常见方法之后，真正困难的问题才出现：面对一个新任务，为什么选这个算法？它究竟解决了哪个瓶颈？一次漂亮的训练曲线能不能说明方法有效？一篇可信的研究，核心不是把最新方法接到环境里，而是把问题、假设、对照、数据划分、统计分析和复现材料连成一条可检查的证据链。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_31_algorithm_map.png"}]],"prev":{"text":"安全不只是扣分：Safe Reinforcement Learning（安全强化学习）如何把奖励、约束与安全屏障接起来","link":"/rl/rl-series-30-safe-rl-constraints"},"next":false},"headers":[],"relativePath":"rl/rl-series-31-research-evaluation.md","filePath":"rl/rl-series-31-research-evaluation.md","lastUpdated":null}'),d={name:"rl/rl-series-31-research-evaluation.md"};function c(p,a,_,u,b,q){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="强化学习学完之后怎么做研究-从算法选择到可信评价" tabindex="-1">强化学习学完之后怎么做研究？从算法选择到可信评价 <a class="header-anchor" href="#强化学习学完之后怎么做研究-从算法选择到可信评价" aria-label="Permalink to &quot;强化学习学完之后怎么做研究？从算法选择到可信评价&quot;">​</a></h1><p>强化学习学到算法推导、训练循环和常见方法之后，真正困难的问题才出现：面对一个新任务，为什么选这个算法？它究竟解决了哪个瓶颈？一次漂亮的训练曲线能不能说明方法有效？一篇可信的研究，核心不是把最新方法接到环境里，而是把问题、假设、对照、数据划分、统计分析和复现材料连成一条可检查的证据链。</p><p>这篇文章把“学完之后怎么做研究”整理成一套可执行的研究协议。主线是先分类问题，再选择足够简单的算法和 baseline（基线），随后固定环境接口，隔离假设，划分训练验证测试数据，使用多个随机种子，报告指标与不确定性，最后把代码、配置和实验记录交付出来。自动驾驶场景还要额外回答安全、延迟、分布外场景和部署闭环问题。</p><h2 id="一、研究不是换一个算法名称" tabindex="-1">一、研究不是换一个算法名称 <a class="header-anchor" href="#一、研究不是换一个算法名称" aria-label="Permalink to &quot;一、研究不是换一个算法名称&quot;">​</a></h2><h3 id="_1-1-从-会实现-切到-要解释" tabindex="-1">1.1 从“会实现”切到“要解释” <a class="header-anchor" href="#_1-1-从-会实现-切到-要解释" aria-label="Permalink to &quot;1.1 从“会实现”切到“要解释”&quot;">​</a></h3><p>会实现 PPO（近端策略优化）或 SAC（软演员—评论家），只能证明你能运行一个训练程序；研究还要求解释为什么该方法适合这个任务，以及性能变化来自哪一个机制。算法名称是实现入口，不是研究问题本身。</p><h3 id="_1-2-把问题写成可证伪命题" tabindex="-1">1.2 把问题写成可证伪命题 <a class="header-anchor" href="#_1-2-把问题写成可证伪命题" aria-label="Permalink to &quot;1.2 把问题写成可证伪命题&quot;">​</a></h3><p>研究命题应当允许实验失败。例如，“在动作受限且反馈稀疏的车道保持任务中，引入动作平滑约束可以降低控制抖动，同时不牺牲成功率”比“用强化学习提升控制效果”更可检验。命题需要明确对象、改动、比较对象、主要指标和可能的反例。</p><h3 id="_1-3-把贡献拆成三种类型" tabindex="-1">1.3 把贡献拆成三种类型 <a class="header-anchor" href="#_1-3-把贡献拆成三种类型" aria-label="Permalink to &quot;1.3 把贡献拆成三种类型&quot;">​</a></h3><p>贡献通常落在算法改动、训练机制或系统工程三个层面。算法改动改变目标函数、网络结构或更新规则；训练机制改变数据收集、课程安排或约束处理；系统工程改变观测、动作接口、延迟补偿或部署链路。三者可以组合，但必须说明主贡献，避免把环境改动、奖励改动和算法改动混在一起。</p><h3 id="_1-4-先写清楚失败条件" tabindex="-1">1.4 先写清楚失败条件 <a class="header-anchor" href="#_1-4-先写清楚失败条件" aria-label="Permalink to &quot;1.4 先写清楚失败条件&quot;">​</a></h3><p>研究开始前就要写出什么结果会推翻命题。若只接受成功曲线，不接受失败场景、训练崩溃和计算代价，实验就会变成寻找支持自己的截图。失败条件应当包含主指标不提升、约束违反增加、对未见场景泛化下降、训练方差扩大或计算预算超限等情况。</p><h2 id="二、问题分类决定算法选择" tabindex="-1">二、问题分类决定算法选择 <a class="header-anchor" href="#二、问题分类决定算法选择" aria-label="Permalink to &quot;二、问题分类决定算法选择&quot;">​</a></h2><h3 id="_2-1-先看动作空间和数据来源" tabindex="-1">2.1 先看动作空间和数据来源 <a class="header-anchor" href="#_2-1-先看动作空间和数据来源" aria-label="Permalink to &quot;2.1 先看动作空间和数据来源&quot;">​</a></h3><p>算法选择首先由动作空间、数据获取方式和环境可交互性决定。离散动作适合从 Q-learning（Q 学习）及其深度版本开始；连续动作需要策略梯度或演员—评论家结构；只能访问固定数据集时，应优先考虑 BC（行为克隆）、DAgger（数据集聚合）或离线强化学习，而不是把在线采样假设硬套进去。</p><h3 id="_2-2-离散动作从-q-学习起步" tabindex="-1">2.2 离散动作从 Q 学习起步 <a class="header-anchor" href="#_2-2-离散动作从-q-学习起步" aria-label="Permalink to &quot;2.2 离散动作从 Q 学习起步&quot;">​</a></h3><p>离散动作任务可以用表格 Q-learning 建立可解释的最小参照，再使用 DQN（深度 Q 学习）处理高维观测。这样做的价值不是追求表格方法的最终分数，而是确认奖励、终止条件、动作映射和回报计算没有根本错误。若最小方法都不能学到合理行为，直接换更大的网络通常只会隐藏问题。</p><h3 id="_2-3-连续控制从简单演员—评论家开始" tabindex="-1">2.3 连续控制从简单演员—评论家开始 <a class="header-anchor" href="#_2-3-连续控制从简单演员—评论家开始" aria-label="Permalink to &quot;2.3 连续控制从简单演员—评论家开始&quot;">​</a></h3><p>连续控制可以先用确定性策略梯度或 TD3（双延迟深度确定性策略梯度）建立基线，再比较 SAC（软演员—评论家）。若任务需要随机策略、探索或多峰动作分布，SAC（软演员—评论家）的熵正则化可能有意义；若动作边界、执行延迟和安全过滤更关键，先把动作缩放、速率限制和外部安全层验证清楚，算法差异才有解释空间。</p><h3 id="_2-4-数据受限时改变研究问题" tabindex="-1">2.4 数据受限时改变研究问题 <a class="header-anchor" href="#_2-4-数据受限时改变研究问题" aria-label="Permalink to &quot;2.4 数据受限时改变研究问题&quot;">​</a></h3><p>固定数据集意味着行为策略与目标策略之间存在分布差异，训练过程无法随意查询环境。此时研究问题应转为“如何在数据支持范围内估计和改进策略”，并报告数据覆盖、行为策略、反事实动作比例和外推风险。把离线数据直接送入在线算法，再把训练回报当成结果，是典型的接口错配。</p><h3 id="_2-5-约束优先时不要只改奖励" tabindex="-1">2.5 约束优先时不要只改奖励 <a class="header-anchor" href="#_2-5-约束优先时不要只改奖励" aria-label="Permalink to &quot;2.5 约束优先时不要只改奖励&quot;">​</a></h3><p>如果任务有碰撞、越界、舒适性或资源上限，约束应当成为问题定义的一部分。可以比较拉格朗日方法、风险敏感目标、可行性过滤器和 CBF（控制屏障函数）等路线，但必须区分“奖励中惩罚了违规”和“系统在约束下有可验证的安全性质”。奖励惩罚只能改变优化偏好，不能自动提供硬安全保证。</p><p><img src="'+l+'" alt="强化学习问题分类与算法选择地图"></p><h2 id="三、baseline-基线-是研究的地基" tabindex="-1">三、Baseline（基线）是研究的地基 <a class="header-anchor" href="#三、baseline-基线-是研究的地基" aria-label="Permalink to &quot;三、Baseline（基线）是研究的地基&quot;">​</a></h2><h3 id="_3-1-无学习基线回答是否值得学习" tabindex="-1">3.1 无学习基线回答是否值得学习 <a class="header-anchor" href="#_3-1-无学习基线回答是否值得学习" aria-label="Permalink to &quot;3.1 无学习基线回答是否值得学习&quot;">​</a></h3><p>自动驾驶控制任务至少应有一个不依赖训练的基线，例如比例控制、Stanley（斯坦利控制器）、纯跟踪或规则控制。它回答的是“复杂学习系统是否超过一个合理的现成方案”，还能帮助检查奖励与最终业务指标是否一致。</p><h3 id="_3-2-经典控制和监督基线回答学到了什么" tabindex="-1">3.2 经典控制和监督基线回答学到了什么 <a class="header-anchor" href="#_3-2-经典控制和监督基线回答学到了什么" aria-label="Permalink to &quot;3.2 经典控制和监督基线回答学到了什么&quot;">​</a></h3><p>经典控制基线提供稳定性和可解释性参照，监督学习基线则提供“从已有数据直接拟合”的参照。若强化学习没有超过监督基线，可能说明在线探索没有带来额外信息；若只在训练场景超过，可能只是记住了场景分布，而不是学会了可迁移策略。</p><h3 id="_3-3-强化学习基线要选择同一范式" tabindex="-1">3.3 强化学习基线要选择同一范式 <a class="header-anchor" href="#_3-3-强化学习基线要选择同一范式" aria-label="Permalink to &quot;3.3 强化学习基线要选择同一范式&quot;">​</a></h3><p>比较 PPO（近端策略优化）、TD3（双延迟深度确定性策略梯度）和 SAC（软演员—评论家）时，应统一观测、动作边界、奖励、最大步数、评估环境和总交互步数。算法可以有各自必须的超参数，但不能给新方法更大的网络、更多的采样预算或更宽松的终止条件，再把差异归因于算法本身。</p><h3 id="_3-4-对照预算要同时看样本和计算" tabindex="-1">3.4 对照预算要同时看样本和计算 <a class="header-anchor" href="#_3-4-对照预算要同时看样本和计算" aria-label="Permalink to &quot;3.4 对照预算要同时看样本和计算&quot;">​</a></h3><p>样本效率关注环境交互次数，计算效率关注 CPU（中央处理器）、GPU（图形处理器）时间和并行规模。模型使用更多参数或更复杂的仿真器时，应同时报告墙钟时间、训练更新次数、峰值显存和环境步数。只按训练轮数对齐，可能让不同方法看到完全不同的数据量。</p><h3 id="_3-5-baseline-基线-弱不等于方法强" tabindex="-1">3.5 Baseline（基线）弱不等于方法强 <a class="header-anchor" href="#_3-5-baseline-基线-弱不等于方法强" aria-label="Permalink to &quot;3.5 Baseline（基线）弱不等于方法强&quot;">​</a></h3><p>一个故意设置不合理的基线会制造虚假提升。基线应使用公开实现或清晰的最小实现，并经过独立调参；若复现公开方法失败，应报告版本、超参数和失败原因，不能只保留对自己有利的结果。研究结论的强度不会超过最强合理对照的强度。</p><p><img src="'+o+'" alt="从无学习控制到强化学习方法的实验矩阵"></p><h2 id="四、假设与消融把因果链拆开" tabindex="-1">四、假设与消融把因果链拆开 <a class="header-anchor" href="#四、假设与消融把因果链拆开" aria-label="Permalink to &quot;四、假设与消融把因果链拆开&quot;">​</a></h2><h3 id="_4-1-把隐含假设写成实验变量" tabindex="-1">4.1 把隐含假设写成实验变量 <a class="header-anchor" href="#_4-1-把隐含假设写成实验变量" aria-label="Permalink to &quot;4.1 把隐含假设写成实验变量&quot;">​</a></h3><p>常见假设包括观测近似满足马尔可夫性、奖励能代表目标、动作可以被执行、环境动力学足够准确、训练数据覆盖关键状态，以及安全过滤器不会改变策略分布。把这些假设写出来后，才能设计针对性的扰动实验，而不是在结果出来后补解释。</p><h3 id="_4-2-一次只改变一个关键因素" tabindex="-1">4.2 一次只改变一个关键因素 <a class="header-anchor" href="#_4-2-一次只改变一个关键因素" aria-label="Permalink to &quot;4.2 一次只改变一个关键因素&quot;">​</a></h3><p>消融实验的基本原则是保持其他条件不变，只移除或替换一个机制。例如研究动作平滑项，就保持网络、优化器、采样预算和评估场景不变，比较有无该项的结果。若同时改奖励、观测堆叠和网络宽度，最终差异只能说明“整套配置不同”。</p><h3 id="_4-3-同时做正向和反向消融" tabindex="-1">4.3 同时做正向和反向消融 <a class="header-anchor" href="#_4-3-同时做正向和反向消融" aria-label="Permalink to &quot;4.3 同时做正向和反向消融&quot;">​</a></h3><p>正向消融加入某个机制，观察性能是否提升；反向消融移除该机制，观察性能是否下降。两者都需要，因为“加入后提升”可能来自额外参数、训练时间或调参机会，而反向消融能更接近判断该机制是否必要。</p><h3 id="_4-4-检查组件之间的交互" tabindex="-1">4.4 检查组件之间的交互 <a class="header-anchor" href="#_4-4-检查组件之间的交互" aria-label="Permalink to &quot;4.4 检查组件之间的交互&quot;">​</a></h3><p>两个组件单独看都有效，组合后可能互相抵消；单独看都无效，组合后也可能产生协同。实验矩阵应覆盖关键组合，至少保留主方法、去掉机制甲、去掉机制乙和同时去掉两者的配置。矩阵不需要无限扩张，但要覆盖论文结论依赖的交互项。</p><h3 id="_4-5-用机制指标解释回报变化" tabindex="-1">4.5 用机制指标解释回报变化 <a class="header-anchor" href="#_4-5-用机制指标解释回报变化" aria-label="Permalink to &quot;4.5 用机制指标解释回报变化&quot;">​</a></h3><p>只看平均回报无法说明为什么变好。动作平滑研究可以报告转向变化率和高频能量，探索研究可以报告新颖状态覆盖，约束研究可以报告最小安全裕度和违规次数，效率研究可以报告环境步数与更新时间。机制指标把“结果变化”连接到“方法如何起作用”。</p><h2 id="五、环境接口决定实验是否可信" tabindex="-1">五、环境接口决定实验是否可信 <a class="header-anchor" href="#五、环境接口决定实验是否可信" aria-label="Permalink to &quot;五、环境接口决定实验是否可信&quot;">​</a></h2><h3 id="_5-1-区分状态、观测和隐藏信息" tabindex="-1">5.1 区分状态、观测和隐藏信息 <a class="header-anchor" href="#_5-1-区分状态、观测和隐藏信息" aria-label="Permalink to &quot;5.1 区分状态、观测和隐藏信息&quot;">​</a></h3><p>环境内部状态不一定能被智能体看到。若训练输入包含未来轨迹、真实加速度、全局目标或测试阶段不可获得的精确地图，结果就不能代表实际系统。应明确观测向量的每一维、坐标系、时间戳、归一化范围和是否使用历史堆叠。</p><h3 id="_5-2-动作接口要写出执行语义" tabindex="-1">5.2 动作接口要写出执行语义 <a class="header-anchor" href="#_5-2-动作接口要写出执行语义" aria-label="Permalink to &quot;5.2 动作接口要写出执行语义&quot;">​</a></h3><p>动作是目标速度、转角、加速度还是离散控制模式，会直接改变问题难度。还要记录动作频率、保持时间、执行延迟、饱和范围、速率限制和安全裁剪顺序。策略输出与车辆真正执行的控制量若不一致，训练目标和部署行为就不是同一个系统。</p><h3 id="_5-3-奖励、终止和截断必须分离" tabindex="-1">5.3 奖励、终止和截断必须分离 <a class="header-anchor" href="#_5-3-奖励、终止和截断必须分离" aria-label="Permalink to &quot;5.3 奖励、终止和截断必须分离&quot;">​</a></h3><p>碰撞造成的终止、达到时间上限造成的截断和任务成功造成的终止，其价值目标含义不同。若把时间截断错误地当作吸收终止，会让算法低估尚未完成轨迹的未来价值。奖励缩放、终止惩罚、成功奖励和每步代价也要按版本记录，避免“同一个环境”实际有多套定义。</p><h3 id="_5-4-控制随机性与环境版本" tabindex="-1">5.4 控制随机性与环境版本 <a class="header-anchor" href="#_5-4-控制随机性与环境版本" aria-label="Permalink to &quot;5.4 控制随机性与环境版本&quot;">​</a></h3><p>随机性可能来自初始状态、交通参与者、传感器噪声、动作噪声、网络初始化和并行执行顺序。环境版本还会受地图、动力学、碰撞检测器和依赖包变化影响。每次运行应保存环境版本、配置文件、随机种子和代码提交号，否则即使种子相同也可能复现不了轨迹。</p><h3 id="_5-5-给环境写最小接口测试" tabindex="-1">5.5 给环境写最小接口测试 <a class="header-anchor" href="#_5-5-给环境写最小接口测试" aria-label="Permalink to &quot;5.5 给环境写最小接口测试&quot;">​</a></h3><p>接口测试不等于训练测试。至少应检查 reset（重置）后的观测形状和范围、step（步进）后的奖励类型、终止与截断标记、动作越界处理、碰撞判定和时间推进。对自动驾驶环境，还应检查坐标转换、车辆尺寸、传感器延迟和安全屏障的输入输出，先排除环境漏洞，再讨论算法效果。</p><h2 id="六、训练、验证、测试不能混用" tabindex="-1">六、训练、验证、测试不能混用 <a class="header-anchor" href="#六、训练、验证、测试不能混用" aria-label="Permalink to &quot;六、训练、验证、测试不能混用&quot;">​</a></h2><h3 id="_6-1-按场景和时间划分数据" tabindex="-1">6.1 按场景和时间划分数据 <a class="header-anchor" href="#_6-1-按场景和时间划分数据" aria-label="Permalink to &quot;6.1 按场景和时间划分数据&quot;">​</a></h3><p>训练集用于更新策略，验证集用于选择模型、超参数和早停点，测试集只用于最终评价。自动驾驶不能只随机切分相邻帧，因为同一条轨迹、同一地图或同一交通参与者会同时出现在不同集合，造成隐性泄漏。更稳妥的切分单位是场景、路线、日期、驾驶员或交通流条件。</p><h3 id="_6-2-验证集服务模型选择" tabindex="-1">6.2 验证集服务模型选择 <a class="header-anchor" href="#_6-2-验证集服务模型选择" aria-label="Permalink to &quot;6.2 验证集服务模型选择&quot;">​</a></h3><p>训练过程中可以用验证集选择 checkpoint（模型检查点）、奖励权重、网络规模和停止时刻，但选择规则必须预先写出。若每隔一轮查看测试集并保留最高分模型，测试集已经参与训练流程，最后的数字不再是未见数据上的独立估计。</p><h3 id="_6-3-测试集只在协议允许时揭晓" tabindex="-1">6.3 测试集只在协议允许时揭晓 <a class="header-anchor" href="#_6-3-测试集只在协议允许时揭晓" aria-label="Permalink to &quot;6.3 测试集只在协议允许时揭晓&quot;">​</a></h3><p>最终测试应包含固定场景、未见场景和具有代表性的困难场景。评估脚本应自动运行并保存原始轨迹，避免人工挑选成功回放。若发现测试集表现异常，应该新增诊断集或重新定义协议，不能反复修改方法直到测试集通过。</p><h3 id="_6-4-超参数搜索也会造成泄漏" tabindex="-1">6.4 超参数搜索也会造成泄漏 <a class="header-anchor" href="#_6-4-超参数搜索也会造成泄漏" aria-label="Permalink to &quot;6.4 超参数搜索也会造成泄漏&quot;">​</a></h3><p>调参次数越多，验证集越像训练信号。记录每次试验和选择理由，限制搜索预算，并保留未参与决策的最终测试集。对于小规模实验，可以用嵌套验证或预注册主配置，至少要把“试过但失败”的配置留下证据。</p><h3 id="_6-5-自动驾驶要分层测试分布" tabindex="-1">6.5 自动驾驶要分层测试分布 <a class="header-anchor" href="#_6-5-自动驾驶要分层测试分布" aria-label="Permalink to &quot;6.5 自动驾驶要分层测试分布&quot;">​</a></h3><p>测试集可以按熟悉场景、参数扰动、组合扰动和 OOD（分布外）场景分层。熟悉场景检查基本功能，扰动场景检查鲁棒性，组合扰动检查交互效应，分布外场景检查边界但不能被包装成常规平均成绩。每层都要报告样本数量和生成规则，不能只给一个总平均。</p><h2 id="七、多随机种子与实验矩阵" tabindex="-1">七、多随机种子与实验矩阵 <a class="header-anchor" href="#七、多随机种子与实验矩阵" aria-label="Permalink to &quot;七、多随机种子与实验矩阵&quot;">​</a></h2><h3 id="_7-1-单次曲线不是证据" tabindex="-1">7.1 单次曲线不是证据 <a class="header-anchor" href="#_7-1-单次曲线不是证据" aria-label="Permalink to &quot;7.1 单次曲线不是证据&quot;">​</a></h3><p>深度强化学习同时受到非凸优化、探索轨迹、环境随机性和并行调度影响。一次运行的最高回报可能是幸运种子，失败也可能是偶然崩溃。研究结论应来自多个独立随机种子的分布，并显示每个种子或至少显示分布范围，而不是只截取最好的曲线。</p><h3 id="_7-2-seed-随机种子-要覆盖完整随机源" tabindex="-1">7.2 Seed（随机种子）要覆盖完整随机源 <a class="header-anchor" href="#_7-2-seed-随机种子-要覆盖完整随机源" aria-label="Permalink to &quot;7.2 Seed（随机种子）要覆盖完整随机源&quot;">​</a></h3><p>seed（随机种子）不仅要传给策略初始化，还应覆盖环境、动作采样、经验回放、数据加载和并行工作进程。框架中的伪随机数、硬件非确定性和多线程调度可能仍然带来差异，所以要把“固定种子”表述为控制一个已知来源，而不是宣称完全确定。</p><h3 id="_7-3-重复次数服从资源和风险" tabindex="-1">7.3 重复次数服从资源和风险 <a class="header-anchor" href="#_7-3-重复次数服从资源和风险" aria-label="Permalink to &quot;7.3 重复次数服从资源和风险&quot;">​</a></h3><p>种子数量没有脱离方差的固定答案。探索不稳定、场景少或结论影响大的实验需要更多重复；资源有限时，至少保证主方法和所有强基线使用相同种子集合，并公开每个种子的原始结果。若只能做少量重复，应降低结论措辞，不要把趋势写成确定优势。</p><h3 id="_7-4-实验矩阵要先锁定主比较" tabindex="-1">7.4 实验矩阵要先锁定主比较 <a class="header-anchor" href="#_7-4-实验矩阵要先锁定主比较" aria-label="Permalink to &quot;7.4 实验矩阵要先锁定主比较&quot;">​</a></h3><p>矩阵的行可以是算法、奖励、观测或安全机制，列可以是场景层、种子和评估指标。主比较必须在实验前锁定，附加探索放在补充实验中。这样既能控制多重比较带来的偶然显著，也能避免结果出来后只挑有利组合。</p><h3 id="_7-5-中途失败也属于实验结果" tabindex="-1">7.5 中途失败也属于实验结果 <a class="header-anchor" href="#_7-5-中途失败也属于实验结果" aria-label="Permalink to &quot;7.5 中途失败也属于实验结果&quot;">​</a></h3><p>数值溢出、策略坍塌、仿真器崩溃或安全约束长期不可行，都是研究对象的一部分。应记录失败运行的原因、发生步数和是否重启；可以按预先定义的规则排除硬件故障，但不能因为分数不好就静默删除。稳定性本身可能就是方法贡献或方法缺陷。</p><h2 id="八、指标与不确定性决定结论强度" tabindex="-1">八、指标与不确定性决定结论强度 <a class="header-anchor" href="#八、指标与不确定性决定结论强度" aria-label="Permalink to &quot;八、指标与不确定性决定结论强度&quot;">​</a></h2><h3 id="_8-1-先定义主指标和决策方向" tabindex="-1">8.1 先定义主指标和决策方向 <a class="header-anchor" href="#_8-1-先定义主指标和决策方向" aria-label="Permalink to &quot;8.1 先定义主指标和决策方向&quot;">​</a></h3><p>主指标应直接对应研究命题，例如成功率、碰撞率、横向误差、舒适性、样本效率或约束违反率。明确“越大越好”还是“越小越好”，并提前定义聚合方式和评价时长。回报只能作为综合指标，不能替代所有业务指标。</p><h3 id="_8-2-自动驾驶要把安全、效率和舒适性拆开" tabindex="-1">8.2 自动驾驶要把安全、效率和舒适性拆开 <a class="header-anchor" href="#_8-2-自动驾驶要把安全、效率和舒适性拆开" aria-label="Permalink to &quot;8.2 自动驾驶要把安全、效率和舒适性拆开&quot;">​</a></h3><p>安全指标可以包括碰撞次数、越界次数、最小时间间隔和安全裕度；任务指标可以包括到达率、跟踪误差和完成时间；舒适性指标可以包括加加速度、转角变化和控制抖动。一个策略可能回报更高却碰撞更多，也可能安全但过于保守，单一分数会掩盖这种权衡。</p><h3 id="_8-3-均值之外报告分位数和最差表现" tabindex="-1">8.3 均值之外报告分位数和最差表现 <a class="header-anchor" href="#_8-3-均值之外报告分位数和最差表现" aria-label="Permalink to &quot;8.3 均值之外报告分位数和最差表现&quot;">​</a></h3><p>均值描述总体水平，中位数减少极端值影响，分位数和最差场景则揭示尾部风险。对于多场景、多种子结果，可以同时报告每个场景分布、跨场景聚合值和失败比例。若只报告最高分或均值，读者无法判断提升是普遍发生，还是由少数容易场景贡献。</p><h3 id="_8-4-用区间表达统计不确定性" tabindex="-1">8.4 用区间表达统计不确定性 <a class="header-anchor" href="#_8-4-用区间表达统计不确定性" aria-label="Permalink to &quot;8.4 用区间表达统计不确定性&quot;">​</a></h3><p>confidence interval（置信区间）应围绕预先选定的统计量计算，不能把标准差、标准误和置信区间混为一谈。样本量较少时，可以使用 bootstrap（自助法）估计聚合指标的区间，并说明重采样单位是运行、场景还是轨迹。区间很宽时，正确结论是证据不足，而不是把点估计写得更精确。</p><h3 id="_8-5-不只比较点估计" tabindex="-1">8.5 不只比较点估计 <a class="header-anchor" href="#_8-5-不只比较点估计" aria-label="Permalink to &quot;8.5 不只比较点估计&quot;">​</a></h3><p>RLiable（可靠强化学习评价工具）相关工作强调，在运行次数有限时，均值和中位数的点估计可能掩盖统计不确定性，性能剖面和区间估计更适合表达跨任务、跨运行的差异。使用这类工具时仍需说明任务权重、归一化基线、聚合规则和异常值处理；工具不能替研究者替换问题定义。</p><p><img src="'+h+'" alt="强化学习多种子评价协议与不确定性报告"></p><h2 id="九、可复现研究如何交付" tabindex="-1">九、可复现研究如何交付 <a class="header-anchor" href="#九、可复现研究如何交付" aria-label="Permalink to &quot;九、可复现研究如何交付&quot;">​</a></h2><h3 id="_9-1-记录能决定结果的配置" tabindex="-1">9.1 记录能决定结果的配置 <a class="header-anchor" href="#_9-1-记录能决定结果的配置" aria-label="Permalink to &quot;9.1 记录能决定结果的配置&quot;">​</a></h3><p>配置文件应包含观测和动作定义、奖励项及权重、网络结构、优化器、学习率、批大小、折扣因子、探索参数、更新频率、评估频率和停止规则。依赖包版本、操作系统、硬件、环境版本与代码提交号也要写入运行记录，不能只保存最终模型。</p><h3 id="_9-2-固定随机性不等于完全确定" tabindex="-1">9.2 固定随机性不等于完全确定 <a class="header-anchor" href="#_9-2-固定随机性不等于完全确定" aria-label="Permalink to &quot;9.2 固定随机性不等于完全确定&quot;">​</a></h3><p>确定性模式可以帮助定位差异，但可能牺牲速度，某些 GPU（图形处理器）算子仍然不保证位级一致。复现目标应分层描述：能否重建环境、能否复现训练流程、结果是否落在报告区间内。把“相同种子得到相同曲线”作为唯一标准，既不现实也不能替代统计复现。</p><h3 id="_9-3-发布轨迹、脚本和统计方法" tabindex="-1">9.3 发布轨迹、脚本和统计方法 <a class="header-anchor" href="#_9-3-发布轨迹、脚本和统计方法" aria-label="Permalink to &quot;9.3 发布轨迹、脚本和统计方法&quot;">​</a></h3><p>可复现交付至少包括环境构建说明、训练入口、评估入口、配置样例、模型检查点、原始运行结果和绘图统计脚本。图表不应只发布图片，还应提供生成图片所需的数据。若数据不能公开，应提供脱敏样例、哈希值、访问条件和替代验证路径。</p><h3 id="_9-4-记录计算预算和失败运行" tabindex="-1">9.4 记录计算预算和失败运行 <a class="header-anchor" href="#_9-4-记录计算预算和失败运行" aria-label="Permalink to &quot;9.4 记录计算预算和失败运行&quot;">​</a></h3><p>实验报告要写清并行环境数量、环境步数、更新次数、墙钟时间、硬件类型和中断重启规则。失败运行、超时和显存不足不能从报告中消失；它们会影响方法的真实工程成本。开源代码也应避免把本机绝对路径、密钥、Token（令牌）或私有数据写入配置和日志。</p><h3 id="_9-5-做一个最小复现实验" tabindex="-1">9.5 做一个最小复现实验 <a class="header-anchor" href="#_9-5-做一个最小复现实验" aria-label="Permalink to &quot;9.5 做一个最小复现实验&quot;">​</a></h3><p>完整复现可能需要很大预算，但可以先提供小规模配置，验证环境接口、损失计算、检查点加载和评价脚本。最小实验应在干净环境中从零运行，产生与示例相同的文件结构和统计字段。小实验跑通后，再扩展到论文预算；否则大规模失败很难判断是代码、环境还是资源问题。</p><p><img src="'+n+'" alt="强化学习研究的代码、配置、数据与统计脚本复现包"></p><h2 id="十、常见误区、自动驾驶路线与31篇之后" tabindex="-1">十、常见误区、自动驾驶路线与31篇之后 <a class="header-anchor" href="#十、常见误区、自动驾驶路线与31篇之后" aria-label="Permalink to &quot;十、常见误区、自动驾驶路线与31篇之后&quot;">​</a></h2><h3 id="_10-1-只换算法不换研究问题" tabindex="-1">10.1 只换算法不换研究问题 <a class="header-anchor" href="#_10-1-只换算法不换研究问题" aria-label="Permalink to &quot;10.1 只换算法不换研究问题&quot;">​</a></h3><p>把 DQN（深度 Q 学习）换成 PPO（近端策略优化）、把 PPO（近端策略优化）换成 SAC（软演员—评论家），并不会自动产生新问题。若观测、奖励、数据和评估协议都没有解释性变化，最多是一次方法移植。研究价值应来自新机制、新约束、新证据或对已有结论的严格检验，而不是算法名更长。</p><h3 id="_10-2-只报最好一次和训练最高点" tabindex="-1">10.2 只报最好一次和训练最高点 <a class="header-anchor" href="#_10-2-只报最好一次和训练最高点" aria-label="Permalink to &quot;10.2 只报最好一次和训练最高点&quot;">​</a></h3><p>训练最高回报可能来自探索阶段的偶然轨迹，测试阶段也可能与训练分布完全不同。应固定评估策略、多个种子和测试场景，报告最终检查点选择规则、均值或中位数、区间和尾部失败。最高点可以作为诊断信息，不能替代最终评价。</p><h3 id="_10-3-把奖励提升当成安全证明" tabindex="-1">10.3 把奖励提升当成安全证明 <a class="header-anchor" href="#_10-3-把奖励提升当成安全证明" aria-label="Permalink to &quot;10.3 把奖励提升当成安全证明&quot;">​</a></h3><p>奖励函数是研究者设计的代理目标，安全是对真实系统状态和约束的判断。奖励提升但碰撞增加，说明代理目标失配；加入惩罚后碰撞减少，也不能推出所有未见场景都安全。自动驾驶必须保留独立的安全监控、动作过滤、降级策略和闭环验证。</p><h3 id="_10-4-从可控玩具任务走向闭环控制" tabindex="-1">10.4 从可控玩具任务走向闭环控制 <a class="header-anchor" href="#_10-4-从可控玩具任务走向闭环控制" aria-label="Permalink to &quot;10.4 从可控玩具任务走向闭环控制&quot;">​</a></h3><p>自动驾驶研究可以从一维速度控制、车道保持和有限障碍交互开始。每个阶段都应先建立经典控制基线，验证动作接口、延迟、奖励和终止，再逐步增加观测噪声、动力学变化、交通参与者和长时域任务。玩具环境用于验证机制，不用于宣称已经解决真实道路问题。</p><h3 id="_10-5-形成自动驾驶研究路线" tabindex="-1">10.5 形成自动驾驶研究路线 <a class="header-anchor" href="#_10-5-形成自动驾驶研究路线" aria-label="Permalink to &quot;10.5 形成自动驾驶研究路线&quot;">​</a></h3><p>纵向控制适合研究速度跟踪、舒适性和安全距离；横向控制适合研究曲率变化、延迟与车道边界；交互决策适合研究部分可观测、多智能体和风险约束；系统级研究则需要把策略、规划、控制、感知延迟和安全屏障接到闭环。每次扩展只引入一个主要复杂度，才知道性能变化来自哪里。</p><p><img src="'+s+'" alt="自动驾驶强化学习研究路线"></p><h3 id="_10-6-31篇之后的进阶方向" tabindex="-1">10.6 31篇之后的进阶方向 <a class="header-anchor" href="#_10-6-31篇之后的进阶方向" aria-label="Permalink to &quot;10.6 31篇之后的进阶方向&quot;">​</a></h3><p>接下来的研究可以沿着可靠性、离线与安全强化学习、因果归因、风险敏感控制、多智能体交互和 sim-to-real（仿真到现实）迁移展开。进入更复杂方向前，先完成一份包含问题命题、强基线、环境接口、消融矩阵、多种子结果、统计区间和复现包的研究记录。能诚实说明方法在哪些条件下有效、在哪些条件下失败，才算真正从“学算法”走到“做研究”。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://arxiv.org/abs/1709.06560" target="_blank" rel="noreferrer">Henderson 等《Deep Reinforcement Learning that Matters（真正重要的深度强化学习）》</a></p><p><a href="https://arxiv.org/abs/2108.13264" target="_blank" rel="noreferrer">RLiable（可靠强化学习评价工具）相关论文《Deep Reinforcement Learning at the Edge of the Statistical Precipice（统计悬崖边缘的深度强化学习）》</a></p>',121)])])}const P=e(d,[["render",c]]);export{f as __pageData,P as default};
